<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {request,ApiError,type Guest} from '../lib/api';
import {streamGomoku,gomokuSeats,type GomokuState,type GomokuGame,type GomokuBet} from '../lib/gomoku';
const props=defineProps<{me:Guest;foreground:boolean}>();const emit=defineEmits<{(e:'auth-expired'):void;(e:'balance',value:number):void}>();
const state=ref<GomokuState|null>(null),busy=ref(false),error=ref(''),notice=ref(''),connected=ref(false),stake=ref(50),betAmount=ref(10),betSide=ref(1),clock=ref(Date.now()),offset=ref(0),canvas=ref<HTMLCanvasElement|null>(null),chosen=ref<{x:number;y:number}|null>(null),showChat=ref(true),chatText=ref(''),chatBusy=ref(false),rules=ref(false);
type Action={action:string;game_id:string;amount?:number;side?:number;x?:number;y?:number;ply?:number;request_id:string};
const pending=ref<Action|null>(null),confirm=ref<{action:Action;title:string;description:string}|null>(null),modal=ref<HTMLElement|null>(null),lines=ref<{id:string;name:string;text:string;at:number;lane:number}[]>([]);
const history=ref<{game:GomokuGame;bets:(GomokuBet&{username:string;nickname:string})[];platform_net:number}[]|null>(null),historyBusy=ref(false);
const game=computed(()=>state.value?.game),mine=computed(()=>state.value?.mine),seats=computed(()=>gomokuSeats(game.value)),side=computed(()=>seats.value.findIndex(p=>p.id===props.me.id)+1),seconds=computed(()=>game.value?Math.max(0,Math.ceil((Date.parse(game.value.deadline)-clock.value-offset.value)/1000)):0),myTurn=computed(()=>game.value?.status==='playing'&&side.value===game.value.turn&&seconds.value>0),active=computed(()=>!!game.value&&game.value.status!=='ended');
const statusLabel=computed(()=>!game.value?'棋桌空着，差个敢落子的':game.value.status==='waiting'?'等待另一位棋手':game.value.status==='betting'?'场外竞猜开放中':game.value.status==='playing'?(game.value.turn===1?'黑方回合':'白方回合'):(game.value.winner?(game.value.winner===1?'黑方获胜':'白方获胜'):'本局结束 · 全额退款'));
const settlement=computed(()=>{const b=mine.value;if(!b?.settled)return '';const net=b.payout-b.amount;return net>0?'这局精神值 +'+net:net<0?'这局精神值 '+net:'本局本金已退回';});
const storageKey='mind-offline-gomoku-pending:'+props.me.id;
let disposed=false,controller:AbortController|undefined,retry:ReturnType<typeof setTimeout>|undefined,poll:ReturnType<typeof setInterval>|undefined,timer:ReturnType<typeof setInterval>|undefined,epoch=0,loading=false,again=false,seq=0,focusBefore:HTMLElement|null=null;
const ended=new Set<string>();
function failure(e:unknown){if(disposed)return;if(e instanceof ApiError&&(e.status===401||e.status===0)){if(e.status===401)emit('auth-expired');return;}error.value=(e as Error).message;}
function remember(){try{if(pending.value)sessionStorage.setItem(storageKey,JSON.stringify(pending.value));else sessionStorage.removeItem(storageKey);}catch{}}
async function load(){if(loading){again=true;return;}loading=true;try{const data=await request<GomokuState>('/gomoku');if(disposed)return;const previous=game.value;if(data.game?.id!==previous?.id||data.game?.moves.length!==previous?.moves.length||data.game?.status!==previous?.status)chosen.value=null;if(data.game?.id!==previous?.id||data.game?.status==='ended'){lines.value=[];if(data.game?.status==='ended')ended.add(data.game.id);}state.value=data;offset.value=Date.parse(data.server_time)-Date.now();emit('balance',data.balance);await nextTick();draw();}catch(e){failure(e);}finally{loading=false;if(again&&!disposed){again=false;void load();}}}
function clearLines(){lines.value=[];}
async function connect(){const n=++epoch;controller?.abort();clearTimeout(retry);connected.value=false;if(!props.foreground||document.visibilityState==='hidden'||disposed){clearLines();return;}const c=new AbortController();controller=c;try{await streamGomoku(c.signal,e=>{if(disposed||n!==epoch)return;if(e.event==='ready'){connected.value=true;void load();}else if(e.event==='ping'){if(state.value)state.value.online=e.data.online;void load();}else if(e.event==='room'){const d=e.data;if(d.kind==='chat'){if(showChat.value&&d.game_id===game.value?.id&&active.value&&!ended.has(d.game_id)){lines.value=lines.value.filter(l=>clock.value-l.at<8000).slice(-7);lines.value.push({id:d.id,name:d.name,text:d.text,at:Date.now(),lane:seq++%5});}}else{if(d.status==='ended'){ended.add(d.game_id);if(d.game_id===game.value?.id)clearLines();}void load();}}});}catch(e){if(e instanceof ApiError&&(e.status===401||e.status===0)){failure(e);return;}}finally{if(n===epoch)connected.value=false;}if(!disposed&&n===epoch&&props.foreground)retry=setTimeout(()=>void connect(),2500);}
function draw(){const c=canvas.value;if(!c)return;c.width=c.height=900;const ctx=c.getContext('2d')!;ctx.scale(1.5,1.5);ctx.fillStyle='#eee3c9';ctx.fillRect(0,0,600,600);const step=544/14;ctx.strokeStyle='#aa9b7c';ctx.lineWidth=.8;for(let n=0;n<15;n++){const p=28+n*step;ctx.beginPath();ctx.moveTo(28,p);ctx.lineTo(572,p);ctx.moveTo(p,28);ctx.lineTo(p,572);ctx.stroke();ctx.fillStyle='#9d9074';ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillText(String(n+1),p,16);ctx.fillText(String(n+1),12,p+3);}
for(const [x,y]of [[3,3],[7,7],[11,3],[3,11],[11,11]]){ctx.beginPath();ctx.arc(28+x*step,28+y*step,3,0,Math.PI*2);ctx.fillStyle='#8e8168';ctx.fill();}
const b=game.value?.board||[];b.forEach((s,i)=>{if(!s)return;const x=28+i%15*step,y=28+Math.floor(i/15)*step;ctx.beginPath();ctx.arc(x,y,16,0,Math.PI*2);ctx.fillStyle=s===1?'#30382c':'#fffef8';ctx.shadowColor='#665e5940';ctx.shadowBlur=3;ctx.shadowOffsetY=2;ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.strokeStyle=s===1?'#20251d':'#c2b79d';ctx.stroke();});const last=game.value?.moves.at(-1);if(last){ctx.fillStyle='#cb876e';ctx.beginPath();ctx.arc(28+last.x*step,28+last.y*step,4,0,Math.PI*2);ctx.fill();}if(chosen.value){ctx.setLineDash([4,3]);ctx.strokeStyle='#9b705d';ctx.lineWidth=2;ctx.strokeRect(28+chosen.value.x*step-17,28+chosen.value.y*step-17,34,34);}}
function selectCell(e:PointerEvent){if(!myTurn.value||busy.value||pending.value)return;const c=canvas.value!;const r=c.getBoundingClientRect(),x=Math.round(((e.clientX-r.left)/r.width*600-28)/(544/14)),y=Math.round(((e.clientY-r.top)/r.height*600-28)/(544/14));if(x<0||x>14||y<0||y>14||game.value!.board[y*15+x])return;chosen.value={x,y};draw();}
function action(name:string,extra:Partial<Action>={}):Action{return {action:name,game_id:game.value?.id||'',request_id:crypto.randomUUID(),...extra};}
async function ask(name:string){if(busy.value||pending.value)return;const amount=name==='create'?stake.value:game.value?.stake||0;let title='',description='',extra:Partial<Action>={};if(name==='create'||name==='join'){title=name==='create'?'坐下，开一局？':'接受对手的押注？';description='本局每位棋手押 '+amount+' 精神值，确认即冻结。胜者净赚 '+amount+'，败者损失 '+amount+'；未开局取消退回本金。';extra={amount};}else if(name==='bet'){title='押'+(betSide.value===1?'黑方':'白方')+' '+betAmount.value+' 点？';description='这是本局最终押注金额，替换原有下注。猜中返还 '+betAmount.value*2+' 点（含本金），猜错损失 '+betAmount.value+' 点；平台独立结算，不影响棋手奖池。';extra={side:betSide.value,amount:betAmount.value};}else if(name==='resign'){title='这局认输？';description='认输将判对手获胜，立即结算棋手押注和所有场外竞猜。';}else if(name==='leave'){title='离开棋桌？';description='尚未开局，本局取消，所有人的押注原路退回。';}else{title='中止这局并退款？';description='对局立即结束，所有棋手和观众的押注全部退回。';}focusBefore=document.activeElement as HTMLElement;confirm.value={action:action(name,extra),title,description};await nextTick();modal.value?.querySelector<HTMLButtonElement>('button')?.focus();}
function closeConfirm(){if(busy.value)return;confirm.value=null;focusBefore?.focus({preventScroll:true});}
function modalKeys(e:KeyboardEvent){if(e.key==='Escape')closeConfirm();if(e.key==='Tab'){const buttons=Array.from(modal.value?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')||[]),first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
async function send(a:Action){if(busy.value)return;busy.value=true;pending.value=a;remember();error.value='';notice.value='';try{await request('/gomoku/action','POST',a);if(disposed)return;pending.value=null;remember();confirm.value=null;chosen.value=null;notice.value='操作已同步';await load();}catch(e){if(e instanceof ApiError&&e.status>=400&&e.status<500){pending.value=null;remember();confirm.value=null;}failure(e);await load();}finally{if(!disposed)busy.value=false;}}
function move(){if(!chosen.value||!myTurn.value||pending.value)return;void send(action('move',{...chosen.value,ply:game.value!.moves.length}));}
async function sendChat(){if(chatBusy.value||!active.value||!chatText.value.trim())return;chatBusy.value=true;try{await request('/gomoku/chat','POST',{game_id:game.value!.id,request_id:crypto.randomUUID(),text:chatText.value.trim()});if(!disposed)chatText.value='';}catch(e){failure(e);}finally{if(!disposed)chatBusy.value=false;}}
async function ledger(){if(history.value){history.value=null;return;}if(historyBusy.value)return;historyBusy.value=true;try{const d=await request<{items:typeof history.value}>('/admin/gomoku');if(!disposed)history.value=d.items;}catch(e){failure(e);}finally{historyBusy.value=false;}}
function visibility(){void connect();if(props.foreground&&document.visibilityState!=='hidden')void load();}
watch(()=>props.foreground,()=>{if(!props.foreground)confirm.value=null;visibility();});watch(showChat,clearLines);
onMounted(()=>{try{const saved=sessionStorage.getItem(storageKey);if(saved)pending.value=JSON.parse(saved);}catch{}void load();void connect();timer=setInterval(()=>{clock.value=Date.now();lines.value=lines.value.filter(l=>clock.value-l.at<8000);},500);poll=setInterval(()=>{if(props.foreground&&document.visibilityState!=='hidden')void load();},15000);document.addEventListener('visibilitychange',visibility);});
onBeforeUnmount(()=>{disposed=true;epoch++;controller?.abort();clearTimeout(retry);clearInterval(poll);clearInterval(timer);document.removeEventListener('visibilitychange',visibility);});
</script>
<template>
<view class="gomoku-room">
 <view class="g-heading"><view><text class="g-eyebrow">带薪游乐场 / 全平台一张棋桌</text><text class="g-title">工位对线室 <text>● ○</text></text><text class="g-sub">今天不卷绩效，卷五颗棋子。</text></view><view class="g-presence"><text :class="{live:connected}">{{connected?'● 实时观战':'○ 正在重连'}}</text><text>{{state?.online||0}} 人在场 · {{state?.balance??me.balance}} 精神值</text></view></view>
 <view class="g-rules-bar"><text>棋手胜负自付 · 场外平台结算 · 仅限站内虚拟精神值</text><button @click="rules=!rules">{{rules?'收起规则':'怎么玩？'}}</button></view>
 <view v-if="rules" class="g-rules">15 × 15 自由五子棋，横竖斜连续达到五子获胜，无禁手、不悔棋。双方入座后随机分配黑白，竞猜开放30秒，封盘后黑方先走。每步120秒，掉线不暂停，超时判负。<br/>棋手等额押注，胜者拿回本金和对方押注；观众只能选一方，猜中返还本金的2倍，猜错归平台。每人场外上限100点，单局总额上限2000点。封盘前可撤注换边，棋手不能押自己这局的场外。<br/>等待入座2分钟超时、开局前离座、平局、系统维护或店长中止，所有人退款。正常胜负、认输和落子超时按胜负结算。弹幕每3秒一条，每局结束立即清空。</view>
 <view v-if="error" class="g-error" role="alert">{{error}}</view><view v-if="pending" class="g-pending">上次操作结果待确认，请勿重复提交。<button :disabled="busy" @click="send(pending!)">{{busy?'确认中…':'重试原操作'}}</button></view>
 <view class="g-layout"><view class="g-board-card">
 <view class="g-players"><view v-for="(p,i) in seats" :key="i" :class="['g-player',{turn:game?.status==='playing'&&game.turn===i+1}]"><view class="g-avatar"><component :is="'img'" v-if="p.avatar" :src="p.avatar" alt="棋手头像"/><text v-else>{{p.name?.slice(0,1)||'?'}}</text></view><view><text class="g-player-name">{{p.name||'等待入座'}}{{p.id===me.id?' · 你':''}}</text><text v-if="!p.id" class="g-player-meta">空位 · 等你来对线</text><text v-else class="g-player-meta">{{game?.status==='waiting'?'待分配黑白':i===0?'● 黑方':'○ 白方'}} · 押 {{game?.stake||0}} 点</text></view></view></view>
 <view class="g-status"><text>{{statusLabel}}</text><text v-if="active">{{seconds}}s</text></view>
 <view class="g-board-wrap"><component :is="'canvas'" ref="canvas" class="g-board" @pointerup="selectCell" aria-label="五子棋棋盘，先选择交叉点，再确认落子"/><view v-if="showChat" class="g-danmaku" aria-hidden="true"><text v-for="line in lines" :key="line.id" :style="{top:(8+line.lane*16)+'%'}">{{line.name}}：{{line.text}}</text></view></view>
 <view class="g-board-foot"><text>{{myTurn?(chosen?'已选第 '+(chosen.y+1)+' 行、第 '+(chosen.x+1)+' 列':'轮到你，点击交叉点选择落点'):game?.status==='playing'?(side?'对手思考中，别替他着急。':'场外可以看棋，也可以发弹幕。'):'先看清押注，再落座。'}}</text><button v-if="myTurn" class="g-primary" :disabled="!chosen||busy||!!pending" @click="move">确认落子</button></view>
 <view v-if="game?.status==='ended'" class="g-result"><text class="g-last-match">上局：{{game.players[0].name||'空位'}} / {{game.players[1].name||'未入座'}} · 座位已释放</text><text>{{game.reason}} · {{game.winner?'这局精神损失费，对面报销。':'精神值已各回各家。'}}</text><text v-if="settlement" class="g-result-money">{{settlement}}<text v-if="mine">（本金 {{mine.amount}}，返还 {{mine.payout}}）</text></text></view>
 </view><view class="g-side">
 <view class="g-panel"><text class="g-section">棋手对赌</text><template v-if="!active"><text class="g-hint">选好每人押注，等一位愿意负责的同事。</text><view class="g-options"><button v-for="n in [0,10,50,100]" :key="n" :class="{selected:stake===n}" @click="stake=n">{{n===0?'友谊局':n+' 点'}}</button></view><button class="g-primary g-wide" :disabled="busy||!!pending" @click="ask('create')">{{game?'再开一局':'入座开一局'}} ↗</button></template>
 <template v-else-if="game?.status==='waiting'"><text class="g-hint">每人 {{game.stake}} 点，胜者净赚 {{game.stake}} 点。</text><button v-if="!side" class="g-primary g-wide" :disabled="busy||!!pending" @click="ask('join')">我来对线 · 入座</button><button v-else class="g-wide" :disabled="busy||!!pending" @click="ask('leave')">离座并退回本金</button></template>
 <template v-else><text class="g-hint">棋手奖池 {{(game?.stake||0)*2}} 点，独立于场外竞猜。</text><button v-if="side" class="g-wide" :disabled="busy||!!pending" @click="ask(game?.status==='playing'?'resign':'leave')">{{game?.status==='playing'?'认输，技不如人':'离座，取消本局'}}</button><text v-else class="g-hint">本局座位已满，下一局再上桌。</text></template></view>
 <view class="g-panel"><text class="g-section">围观押一手</text><text class="g-hint">固定1赔1净收益 · 押100，猜中返200</text><view class="g-market"><view><text>● 押黑方</text><text>{{state?.totals[0]||0}} 点</text></view><view><text>○ 押白方</text><text>{{state?.totals[1]||0}} 点</text></view></view>
 <text class="g-hint">场外累计 {{(state?.totals[0]||0)+(state?.totals[1]||0)}} / 2000 点 · 每人最多100点</text>
 <template v-if="game?.status==='betting'&&!side"><view class="g-options"><button :class="{selected:betSide===1}" @click="betSide=1">黑方赢</button><button :class="{selected:betSide===2}" @click="betSide=2">白方赢</button></view><view class="g-options"><button v-for="n in [10,50,100]" :key="n" :class="{selected:betAmount===n}" @click="betAmount=n">{{n}} 点</button></view><button class="g-primary g-wide" :disabled="busy||!!pending||seconds<=0" @click="ask('bet')">{{mine?.amount?'调整押注':'确认押注'}}</button><button v-if="mine?.amount" class="g-wide" :disabled="busy||!!pending||seconds<=0" @click="send(action('bet',{amount:0,side:mine.side}))">撤回场外押注</button></template>
 <text v-else class="g-hint">{{side&&active?'你是本局棋手，不能参与场外竞猜。':game?.status==='playing'?'已经封盘，等结果吧。':'双方入座后开放30秒竞猜。'}}</text><text v-if="mine?.lane==='audience'&&mine.amount" class="g-mybet">你押了{{mine.side===1?'黑':'白'}}方 {{mine.amount}} 点{{mine.settled?' · 已结算':' · 本金已冻结'}}</text></view>
 <view class="g-panel"><view class="g-chat-heading"><text class="g-section">场外碎碎念</text><button @click="showChat=!showChat">{{showChat?'关闭弹幕':'开启弹幕'}}</button></view><text class="g-hint">每局结束弹幕全清空，不保留记录。</text><component :is="'input'" class="g-chat-input" :value="chatText" @input="chatText=($event.target as HTMLInputElement).value" maxlength="40" :disabled="!active" placeholder="棋可以看不懂，气势不能输…" @keydown.enter.prevent="sendChat" aria-label="发送本局弹幕"/><button class="g-wide" :disabled="!active||chatBusy||!chatText.trim()" @click="sendChat">{{chatBusy?'发送中…':'发射弹幕 ↗'}}</button></view>
 <view v-if="me.is_admin" class="g-panel"><text class="g-section">店长值班</text><button class="g-wide" :disabled="historyBusy" @click="ledger">{{history?'收起账本':'查看最近20局账本'}}</button><button v-if="active" class="g-wide" :disabled="busy||!!pending" @click="ask('abort')">中止本局并全额退款</button><text class="g-hint">弹幕禁言沿用摸鱼大厅的店长禁言管理。</text></view>
 </view></view>
 <view v-if="history" class="g-ledger"><text class="g-section">最近20局 · 平台收支仅含场外竞猜</text><view v-for="row in history" :key="row.game.id" class="g-ledger-row"><text>{{row.game.players[0].name||'空位'}} vs {{row.game.players[1].name||'空位'}} · {{row.game.reason||row.game.status}} · 平台净收支 {{row.platform_net}}</text><text v-for="b in row.bets" :key="b.username">@{{b.username}} · {{b.lane==='player'?'棋手':'场外'}} · {{b.side===1?'黑':'白'}}方 · 押 {{b.amount}} / 返 {{b.payout}} · {{b.settled?'已结算':'冻结中'}}</text></view></view>
 <view v-if="confirm" class="g-backdrop" @click.self="closeConfirm" @keydown="modalKeys"><component :is="'section'" ref="modal" class="g-dialog" role="dialog" aria-modal="true" aria-labelledby="g-confirm-title"><text class="g-eyebrow">精神值也是辛苦摸来的</text><text id="g-confirm-title" class="g-section">{{confirm.title}}</text><text class="g-confirm-copy">{{confirm.description}}</text><view class="g-confirm-buttons"><component :is="'button'" class="g-native" :disabled="busy" @click="closeConfirm">再想想</component><component :is="'button'" class="g-native g-native-primary" :disabled="busy" @click="send(confirm!.action)">{{busy?'处理中…':'确认'}}</component></view></component></view>
</view>
